465	LiaStarExtension::Subsolver& LiaStarExtension::getSubsolver(Node lambda)
466	{
467	  // Return the persistent incremental subsolver for `lambda`, creating and
468	  // seeding it on first use. It is used by the lazy strategy to enumerate the
469	  // convex cells of the predicate's satisfying region.
470	  auto it = d_subsolvers.find(lambda);
471	  if (it != d_subsolvers.end())
472	  {
473	    return it->second;
474	  }
475	  Subsolver& sub = d_subsolvers[lambda];
476	
477	  Options subOptions;
478	  // we read the model below to construct the disjunct.
479	  subOptions.write_smt().produceModels = true;
480	  sub.engine = std::make_unique<SolverEngine>(d_nm, &subOptions);
481	  sub.engine->setIsInternalSubsolver();
482	  LogicInfo info("QF_LIA");
483	  sub.engine->setLogic(info);
484	  sub.engine->setOption("incremental", "true");
485	
486	  // The base assertion is the membership predicate (with ites and negations
487	  // eliminated) conjoined with the non-negativity of the lambda's variables.
488	  Node base = LiaStarUtils::removeItesAndNots(lambda[1], &d_env);
489	  std::vector<Node> conjuncts{base};
490	  for (Node var : lambda[0])
491	  {
492	    conjuncts.push_back(d_nm->mkNode(Kind::GEQ, var, d_zero));
493	  }
494	  base =
495	      conjuncts.size() == 1 ? conjuncts[0] : d_nm->mkNode(Kind::AND, conjuncts);
496	
497	  // The lambda's bound variables appear free in `base`. A formula with free
498	  // (bound) variables cannot be asserted to a subsolver, so we replace them
499	  // with fresh free constants and remember the mapping so the disjunct built
500	  // from the model can be substituted back into bound-variable space.
501	  for (Node var : lambda[0])
502	  {
503	    if (var.getKind() == Kind::BOUND_VARIABLE)
504	    {
505	      sub.from.push_back(var);
506	      sub.to.push_back(d_nm->mkDummySkolem("liastar", var.getType()));
507	    }
508	  }
509	  if (!sub.from.empty())
510	  {
511	    base = base.substitute(
512	        sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
513	  }
514	  sub.base = base;
515	  sub.engine->assertFormula(base);
516	  return sub;
517	}
518	
519	void LiaStarExtension::lazyCheckStar(Node literal, Node lambda)
520	{
521	  // Lazy reduction: drive one refinement round for `literal`. Stop refining
522	  // once the literal has been fully reduced (its term marked processed).
523	  if (std::find(
524	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
525	      != d_processedStarTerms.end())
526	  {
527	    return;
528	  }
529	
530	  // The persistent incremental subsolver for this lambda. On first use it is
531	  // seeded with the (nonnegative) predicate.
532	  Subsolver& sub = getSubsolver(lambda);
533	
534	  // Refine the subsolver with the cone-disjuncts discovered since the previous
535	  // round. The disjuncts are stored in bound-variable space, so map them to
536	  // skolem space first. Two strategies (option arith-liastar-push-pop):
537	  // - accumulate (default): assert the negation of each new disjunct, one
538	  //   assertFormula per disjunct, so each disjunct is asserted exactly once
539	  //   and the subsolver keeps everything it learned about covered regions;
540	  // - push/pop: the refined formula -- the negated union of every disjunct
541	  //   found so far -- subsumes the previous round's, so pop the previous
542	  //   refined formula and assert the new one in a fresh frame: the subsolver
543	  //   always holds just the base predicate (at the base user level) plus a
544	  //   single refined formula, keeping the number of live assertions (and the
545	  //   formulas cached per assertion) constant across rounds.
546	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
547	      d_lazyCones[lambda];
548	  if (sub.negated < pairs.size())
549	  {
550	    bool pushPop = options().arith.arithLiaStarPushPop;
551	    for (size_t i = sub.negated; i < pairs.size(); i++)
552	    {
553	      Node disjunct = pairs[i].first;
554	      if (!sub.from.empty())
555	      {
556	        disjunct = disjunct.substitute(
557	            sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
558	      }
559	      if (pushPop)
560	      {
561	        sub.covered = sub.covered.isNull()
562	                          ? disjunct
563	                          : d_nm->mkNode(Kind::OR, sub.covered, disjunct);
564	      }
565	      else
566	      {
567	        sub.engine->assertFormula(disjunct.notNode());
568	      }
569	    }
570	    sub.negated = pairs.size();
571	    if (pushPop)
572	    {
573	      if (sub.pushed)
574	      {
575	        sub.engine->pop();
576	      }
577	      sub.engine->push();
578	      sub.engine->assertFormula(sub.covered.notNode());
579	      sub.pushed = true;
580	    }
581	  }
582	
583	  lazyHilbert(literal, sub);
584	}
585	
586	std::pair<std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>,
587	          std::vector<Node>>
588	LiaStarExtension::getCones(
589	    Node n, const std::vector<std::pair<std::vector<std::string>, Node>>& pairs)
590	{
591	  // Eager path: build a cone for every DNF disjunct (`pairs`) and accumulate
592	  // the star constraints over all of them. Returns (cones, starConstraints):
593	  // the cones (paired with their predicate node) are used to build the
594	  // membership encoding for the debug trace, and starConstraints is the star
595	  // encoding that becomes the reduction lemma.
596	  std::vector<std::pair<Node, Cone<Integer>>> cones;
597	  std::vector<Node> vec(n.begin() + 1, n.end());
598	  size_t dimension = vec.size();
599	  std::vector<std::pair<Vector, std::vector<Vector>>> lambdas;
600	  std::vector<Node> starConstraints;
601	
602	  for (size_t i = 0; i < pairs.size(); i++)
603	  {
604	    const std::pair<std::vector<std::string>, Node>& pair = pairs[i];
605	    Trace("liastar-ext") << "---------------------------" << std::endl;
606	    Trace("liastar-ext") << "Cone for node " << i << std::endl
607	                         << pair.second << std::endl;
608	
609	    Cone<Integer> cone = LiaStarUtils::buildCone(dimension, pair.first);
610	    if (LiaStarUtils::isEmptyCone(cone))
611	    {
612	      // an infeasible disjunct contributes nothing to the star
613	      Trace("liastar-ext") << "empty cone" << std::endl;
614	      continue;
615	    }
616	
617	    for (const auto& generator : getConeGenerators(cone, dimension))
618	    {
619	      Trace("liastar-ext") << toString(generator) << std::endl;
620	      // Build the star encoding of this generator over fresh skolems (the
621	      // constraints are asserted at the top level, not under a quantifier) and
622	      // accumulate its side constraints and its (point, rays) contribution.
623	      std::vector<Node> vars, constraints;
624	      Vector point;
625	      std::vector<Vector> rays;
626	      LiaStarUtils::getGeneratorBody(dimension,
627	                                     generator,
628	                                     cone.getHilbertBasis(),
629	                                     /*star=*/true,
630	                                     /*useSkolems=*/true,
631	                                     d_nm,
632	                                     vars,
633	                                     constraints,
634	                                     point,
635	                                     rays);
636	      starConstraints.insert(
637	          starConstraints.end(), constraints.begin(), constraints.end());
638	      lambdas.push_back({point, rays});
639	    }
640	    cones.push_back({pair.second, cone});
641	  }
642	
643	  // The star vector equals the sum of every cone's contribution.
644	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
645	  starConstraints.insert(starConstraints.end(), sums.begin(), sums.end());
646	
647	  return std::make_pair(cones, starConstraints);
648	}
