898	Node LiaStarExtension::getModelDisjunct(
899	    MainEnum& en, const std::map<Node, Node>& arithModel)
900	{
901	  // Build one disjunct of the satisfying region by fixing every atom of the
902	  // base predicate to its truth value in the candidate arithmetic model. This
903	  // mirrors `LiaStarUtils::getDisjunct`, with the subsolver's getValue
904	  // replaced by substitution with the main solver's model.
905	  std::vector<Node> keys;
906	  std::vector<Node> values;
907	  for (const auto& [key, value] : arithModel)
908	  {
909	    keys.push_back(key);
910	    values.push_back(value);
911	  }
912	  // The enumeration skolems may be missing from the arithmetic model map
913	  // (e.g. when their atoms were not asserted to the theory this round); fall
914	  // back to the linear solver's candidate model value for them.
915	  for (const Node& sk : en.to)
916	  {
917	    if (arithModel.find(sk) == arithModel.end())
918	    {
919	      Node value = d_arith.getCandidateModelValue(sk);
920	      if (value.isNull() || !value.isConst())
921	      {
922	        return Node();
923	      }
924	      keys.push_back(sk);
925	      values.push_back(value);
926	    }
927	  }
928	  auto evaluate = [&](Node n) {
929	    return rewrite(
930	        n.substitute(keys.begin(), keys.end(), values.begin(), values.end()));
931	  };
932	
933	  std::vector<Node> atoms;
934	  std::unordered_set<Node> visited;
935	  LiaStarUtils::collectAtoms(en.base, atoms, visited);
936	  std::vector<Node> literals;
937	  for (const Node& atom : atoms)
938	  {
939	    Node value = evaluate(atom);
940	    Node literal;
941	    if (value == d_true)
942	    {
943	      // the atom is true in the model: keep it as is
944	      literal = atom;
945	    }
946	    else if (value == d_false)
947	    {
948	      if (atom.getKind() == Kind::EQUAL && atom[0].getType().isInteger())
949	      {
950	        // A disequality is not convex (it is the union of two half-spaces),
951	        // so it cannot be a single cone. Pick the strict inequality on the
952	        // side that the model satisfies.
953	        Node lhs = evaluate(atom[0]);
954	        Node rhs = evaluate(atom[1]);
955	        if (!lhs.isConst() || !rhs.isConst())
956	        {
957	          return Node();
958	        }
959	        Kind k = lhs.getConst<Rational>() > rhs.getConst<Rational>()
960	                     ? Kind::GT
961	                     : Kind::LT;
962	        literal = d_nm->mkNode(k, atom[0], atom[1]);
963	      }
964	      else
965	      {
966	        // the atom is false in the model: negate it
967	        literal = atom.notNode();
968	      }
969	    }
970	    else
971	    {
972	      // the atom has no determined value under the candidate model
973	      return Node();
974	    }
975	    if (!en.from.empty())
976	    {
977	      // substitute the fresh skolems back to the lambda's bound variables.
978	      literal = literal.substitute(
979	          en.to.begin(), en.to.end(), en.from.begin(), en.from.end());
980	    }
981	    literals.push_back(literal);
982	  }
983	  if (literals.empty())
984	  {
985	    return d_true;
986	  }
987	  if (literals.size() == 1)
988	  {
989	    return literals[0];
990	  }
991	  return d_nm->mkNode(Kind::AND, literals);
992	}
993	
994	void LiaStarExtension::advanceStage(MainEnum& en, Node skolemDisjunct)
995	{
996	  // Open a new enumeration stage: a fresh guard that activates the previous
997	  // stage's constraints plus the negation of the newly covered cell, so the
998	  // current guard always activates `base and not(D_1) ... and not(D_k)` with
999	  // two constant-size lemmas per stage.
1000	  Node g = d_nm->mkDummySkolem("liastarEnumGuard", d_nm->booleanType());
1001	  g = d_astate.getValuation().ensureLiteral(g);
1002	  d_im.preferPhase(g, true);
1003	  addEnumLemma(g.impNode(en.guard));
1004	  addEnumLemma(g.impNode(skolemDisjunct.notNode()));
1005	  en.guard = g;
1006	}
1007	
1008	void LiaStarExtension::emitDriverLemma(Node literal, MainEnum& en)
1009	{
1010	  // Emit, once per (literal, stage), the driver lemma
1011	  //     literal => (p[v] or star or guard).
1012	  // If the literal is asserted but the model certifies it neither via p[v]
1013	  // nor via the star under-approximation, the driver forces the stage guard,
1014	  // which places the enumeration skolems in a cell not covered by any cone --
1015	  // the next round then reads that cell off the model. Once every cell is
1016	  // covered the guard branch closes by conflict and only the certified
1017	  // branches remain (with `star` then exact). The lemma is satisfiability
1018	  // preserving: in any model where v is in the star set but outside the
1019	  // discovered approximation, some cell of the predicate is still uncovered,
1020	  // and the model extends to one placing the (fresh) skolems in it.
1021	  auto it = d_lastDriver.find(literal);
1022	  if (it != d_lastDriver.end() && it->second == en.guard)
1023	  {
1024	    return;
1025	  }
1026	  Node pv = LiaStarUtils::getVectorPredicate(literal, d_nm).first;
1027	  std::vector<Node> branches{pv};
1028	  auto starIt = d_lastStarLia.find(literal);
1029	  if (starIt != d_lastStarLia.end())
1030	  {
1031	    branches.push_back(starIt->second);
1032	  }
1033	  branches.push_back(en.guard);
1034	  addEnumLemma(literal.impNode(d_nm->mkNode(Kind::OR, branches)));
1035	  d_lastDriver[literal] = en.guard;
1036	}
