251	void TheoryArith::postCheck(Effort level)
252	{
253	  d_im.reset();
254	  Trace("arith-check") << "TheoryArith::postCheck " << level << std::endl;
255	  if (Theory::fullEffort(level))
256	  {
257	    // Make sure we don't have old lemmas floating around. This can happen if we
258	    // didn't actually reach a last call effort check, but backtracked for some
259	    // other reason. In such a case, these lemmas are likely to be irrelevant
260	    // and possibly even harmful. If we produce proofs, their proofs have most
261	    // likely been deallocated already as well.
262	    d_im.clearPending();
263	    d_im.clearWaitingLemmas();
264	  }
265	  // we don't check at last call
266	  Assert(level != Theory::EFFORT_LAST_CALL);
267	  // otherwise, check with the linear solver
268	  if (d_internal.postCheck(level))
269	  {
270	    // linear solver emitted a conflict or lemma, return
271	    return;
272	  }
273	  if (d_im.hasSent())
274	  {
275	    return;
276	  }
277	
278	  if (Theory::fullEffort(level))
279	  {
280	    d_arithModelCache.clear();
281	    d_arithModelCacheIllTyped.clear();
282	    d_arithModelCacheSubs.clear();
283	    d_arithModelCacheSet = false;
284	    std::set<Node> termSet;
285	
286	#ifdef CVC5_USE_NORMALIZ
287	    if (d_liaStarExtension != nullptr)
288	    {
289	      updateModelCache(termSet);
290	      // Check at full effort. This may either send lemmas or otherwise
291	      // buffer lemmas that we send at last call.
292	      d_liaStarExtension->checkFullEffort(d_arithModelCache, termSet);
293	      // if we already sent a lemma, we are done
294	      if (d_im.hasSent())
295	      {
296	        return;
297	      }
298	    }
299	#endif /* CVC5_USE_NORMALIZ */
300	
301	    if (d_nonlinearExtension != nullptr)
302	    {
303	      updateModelCache(termSet);
304	      // Check at full effort. This may either send lemmas or otherwise
305	      // buffer lemmas that we send at last call.
306	      d_nonlinearExtension->checkFullEffort(d_arithModelCache, termSet);
307	      // if we already sent a lemma, we are done
308	      if (d_im.hasSent())
309	      {
310	        return;
311	      }
312	    }
313	    else if (d_internal.foundNonlinear())
314	    {
315	      // set incomplete
316	      d_im.setModelUnsound(IncompleteId::ARITH_NL_DISABLED);
317	    }
318	    // If we won't be doing a last call effort check (which implies that
319	    // models will be computed), we must sanity check the integer model
320	    // from the linear solver now. We also must update the model cache
321	    // if we did not do so above.
322	    if (d_nonlinearExtension == nullptr)
323	    {
324	      updateModelCache(termSet);
325	    }
326	    sanityCheckIntegerModel();
327	    // Now, finalize the model cache, which constructs a substitution to be
328	    // used for getEqualityStatus.
329	    finalizeModelCache();
330	  }
331	}
