333	bool TheoryArith::preNotifyFact(
334	    TNode atom, bool pol, TNode fact, bool isPrereg, bool isInternal)
335	{
336	  Trace("arith-check") << "TheoryArith::preNotifyFact: " << fact
337	                       << ", isPrereg=" << isPrereg
338	                       << ", isInternal=" << isInternal << std::endl;
339	  // ToDo: review this if statement
340	  if (atom.getKind() == Kind::STAR_CONTAINS)
341	  {
342	    // star contains in not a standard arith predicate, so we return false
343	    // to indicate this fact is not processed at preNotifyFact.
344	    return false;
345	  }
346	  // We do not assert to the equality engine of arithmetic in the standard way,
347	  // hence we return "true" to indicate we are finished with this fact.
348	  bool ret = true;
349	  if (options().arith.arithEqSolver)
350	  {
351	    // the equality solver may indicate ret = false, after which the assertion
352	    // will be asserted to the equality engine in the default way.
353	    ret = d_eqSolver->preNotifyFact(atom, pol, fact, isPrereg, isInternal);
354	  }
355	  // we also always also notify the internal solver
356	  d_internal.preNotifyFact(fact);
357	  return ret;
358	}
