627	Node LiaStarUtils::getDisjunct(Node assertion,
628	                               const std::vector<Node>& from,
629	                               const std::vector<Node>& to,
630	                               Env* e,
631	                               SolverEngine* smte)
632	{
633	  NodeManager* nm = e->getNodeManager();
634	  // The subsolver `smte` already has `assertion` (and the negations of the
635	  // previously discovered cone-disjuncts) asserted; we only check it and read
636	  // the model. `assertion` is passed here only to enumerate the atoms whose
637	  // truth value the disjunct fixes.
638	  Result result = smte->checkSat();
639	  if (result.getStatus() == Result::Status::UNSAT)
640	  {
641	    // No region of the predicate is left uncovered: the cone encoding is exact.
642	    return nm->mkConst<>(false);
643	  }
644	  // Build one disjunct of the satisfying region by fixing every atom of the
645	  // formula to its truth value in the model. The result is a conjunction of
646	  // literals that implies the formula. We deliberately do not read the
647	  // arithmetic theory's facts: the linear solver eliminates variables using
648	  // equalities, so those equalities would be missing from the facts and the
649	  // resulting cone would be too coarse.
650	  std::vector<Node> atoms;
651	  std::unordered_set<Node> visited;
652	  collectAtoms(assertion, atoms, visited);
653	  std::vector<Node> literals;
654	  for (const Node& atom : atoms)
655	  {
656	    Node literal;
657	    if (smte->getValue(atom).getConst<bool>())
658	    {
659	      // the atom is true in the model: keep it as is
660	      literal = atom;
661	    }
662	    else if (atom.getKind() == Kind::EQUAL && atom[0].getType().isInteger())
663	    {
664	      // A disequality is not convex (it is the union of two half-spaces), so it
665	      // cannot be a single cone. Pick the strict inequality on the side that
666	      // the model satisfies.
667	      Rational lhs = smte->getValue(atom[0]).getConst<Rational>();
668	      Rational rhs = smte->getValue(atom[1]).getConst<Rational>();
669	      Kind k = lhs > rhs ? Kind::GT : Kind::LT;
670	      literal = nm->mkNode(k, atom[0], atom[1]);
671	    }
672	    else
673	    {
674	      // the atom is false in the model: negate it
675	      literal = atom.notNode();
676	    }
677	    if (!from.empty())
678	    {
679	      // substitute the fresh constants back to the lambda's bound variables.
680	      literal =
681	          literal.substitute(to.begin(), to.end(), from.begin(), from.end());
682	    }
683	    literals.push_back(literal);
684	  }
685	  if (literals.empty())
686	  {
687	    return nm->mkConst<>(true);
688	  }
689	  if (literals.size() == 1)
690	  {
691	    return literals[0];
692	  }
693	  return nm->mkNode(Kind::AND, literals);
694	}
