696	void LiaStarUtils::collectAtoms(Node n,
697	                                std::vector<Node>& atoms,
698	                                std::unordered_set<Node>& visited)
699	{
700	  // Walk the boolean skeleton of `n` and collect its atomic predicates (the
701	  // boolean leaves) in deterministic order, deduplicating via `visited`.
702	  if (!visited.insert(n).second)
703	  {
704	    return;
705	  }
706	  switch (n.getKind())
707	  {
708	    case Kind::CONST_BOOLEAN: return;
709	    case Kind::NOT:
710	    case Kind::AND:
711	    case Kind::OR:
712	    case Kind::IMPLIES:
713	    case Kind::XOR:
714	    case Kind::ITE:
715	    {
716	      for (const Node& child : n)
717	      {
718	        if (child.getType().isBoolean())
719	        {
720	          collectAtoms(child, atoms, visited);
721	        }
722	      }
723	      return;
724	    }
725	    default:
726	    {
727	      // an atomic predicate (comparison or boolean equality)
728	      atoms.push_back(n);
729	      return;
730	    }
731	  }
732	}
