734	Result LiaStarUtils::cvc5CheckSat(const std::vector<Node>& freeVariables,
735	                                  Node assertion,
736	                                  Env* e)
737	{
738	  // Check the satisfiability of `assertion` with a fresh cvc5 subsolver. All
739	  // variables are constrained to be non-negative (the star set lives in the
740	  // non-negative orthant). Genuine bound variables are existentially quantified;
741	  // free constants are left in place (checking a formula with free constants is
742	  // the same as checking its existential closure).
743	  Options subOptions;
744	  SubsolverSetupInfo ssi(*e, subOptions);
745	
746	  Result result;
747	  if (freeVariables.size() == 0)
748	  {
749	    result = checkWithSubsolver(assertion, ssi);
750	  }
751	  else
752	  {
753	    NodeManager* nm = e->getNodeManager();
754	    Node zero = nm->mkConstInt(Rational(0));
755	    std::vector<Node> boundVariables;
756	    for (Node var : freeVariables)
757	    {
758	      assertion = assertion.andNode(nm->mkNode(Kind::GEQ, var, zero));
759	      if (var.getKind() == Kind::BOUND_VARIABLE)
760	      {
761	        boundVariables.push_back(var);
762	      }
763	    }
764	    Node query = assertion;
765	    if (!boundVariables.empty())
766	    {
767	      Node varList = nm->mkNode(Kind::BOUND_VAR_LIST, boundVariables);
768	      query = nm->mkNode(Kind::EXISTS, varList, assertion);
769	    }
770	    result = checkWithSubsolver(query, ssi);
771	  }
772	  Trace("liastar-ext-cvc5CheckSat")
773	      << "Conjunction: " << assertion << " is " << result << std::endl;
774	  return result;
775	}
