777	Cone<Integer> LiaStarUtils::buildCone(
778	    size_t dimension, const std::vector<std::string>& constraints)
779	{

780	  // The single point of contact with libnormaliz. Render the constraint rows
781	  // into a Normaliz "symbolic constraints" input block over `dimension`-many
782	  // variables, restricted to the non-negative orthant, asking for the Hilbert
783	  // basis and the module generators. Then construct the cone and compute those
784	  // two properties.
785	  libnormaliz::OptionsHandler options;
786	
787	  std::map<libnormaliz::PolyParam::Param, std::vector<std::string>>
788	      poly_param_input;
789	  std::map<libnormaliz::NumParam::Param, long> num_param_input;
790	  std::map<libnormaliz::BoolParam::Param, bool> bool_param_input;
791	
792	  libnormaliz::renf_class_ptr number_field_ref;
793	
794	  std::stringstream ss;
795	  ss << "amb_space " << dimension << std::endl;
796	  ss << "constraints " << constraints.size() << " symbolic" << std::endl;
797	  for (const auto& constraint : constraints)
798	  {
799	    ss << constraint << std::endl;
800	  }
801	  ss << "nonnegative" << std::endl;
802	  ss << "HilbertBasis" << std::endl;
803	  ss << "ModuleGenerators" << std::endl;
804	  Trace("liastar-ext") << "normaliz input:" << std::endl;
805	  Trace("liastar-ext") << ss.str() << std::endl;
806	
807	  // here we use mpq_class instead of Integer (or mpz_class)
808	  // because libnormaliz.so only has implementation for
809	  // readNormalizInput<mpq_class>
810	  std::map<Type::InputType, libnormaliz::Matrix<mpq_class>> input;
811	  input = libnormaliz::readNormalizInput<mpq_class>(ss,
812	                                                    options,
813	                                                    num_param_input,
814	                                                    bool_param_input,
815	                                                    poly_param_input,
816	                                                    number_field_ref);
817	  Cone<Integer> cone(input);
818	  cone.setNonnegative(true);
819	  // always use infinite precision for integers
820	  cone.deactivateChangeOfPrecision();
821	  cone.compute(ConeProperty::HilbertBasis);
822	  cone.compute(ConeProperty::ModuleGenerators);
823	  return cone;
824	}
