826	bool LiaStarUtils::isEmptyCone(Cone<Integer>& cone)
827	{
828	  // AffineDim is only computed for inhomogeneous cones; -1 marks the
829	  // (inhomogeneous) constraint system as infeasible, i.e. the cone is empty.
830	  if (cone.isInhomogeneous())
831	  {
832	    return cone.getAffineDim() == -1;
833	  }
834	  return false;
835	}
