837	Result LiaStarUtils::normalizCheckSat(Node variables, Node assertion)
838	{
839	  // Use Normaliz as a satisfiability oracle for a single conjunction of linear
840	  // constraints: the conjunction is satisfiable over the non-negative integers
841	  // iff the corresponding cone is non-empty. Only the UNSAT verdict is
842	  // meaningful here; otherwise an unknown Result is returned.
843	  Trace("liastar-normalizCheckSat")
844	      << "---------------------------" << std::endl;
845	  Trace("liastar-normalizCheckSat")
846	      << "Cone for node: " << assertion << std::endl;
847	
848	  const std::vector<std::pair<std::vector<std::string>, Node>>& matrices =
849	      getMatrices(variables, assertion);
850	  Cone<Integer> cone = buildCone(variables.getNumChildren(), matrices[0].first);
851	
852	  Result result;
853	  if (isEmptyCone(cone))
854	  {
855	    Trace("liastar-ext") << "empty cone" << std::endl;
856	    result = Result(Result::Status::UNSAT);
857	  }
858	  Trace("liastar-ext-normalizCheckSat")
859	      << "Constraints are " << result << std::endl;
860	  return result;
861	}
