883	std::pair<std::vector<std::string>, Node> LiaStarUtils::getMatrix(
884	    Node variables, Node n)
885	{
886	  // Render a single cone (a conjunction of linear (in)equalities, or one
887	  // atom/boolean constant) into a list of Normaliz "symbolic" constraint
888	  // strings paired with the original node `n`. The boolean constants are
889	  // encoded as the trivially-true row "x[1] = x[1];" and the infeasible row
890	  // "1 = 0;".
891	  Assert(n.getType().isBoolean()) << "n: " << n << std::endl;
892	  Kind k = n.getKind();
893	  switch (k)
894	  {
895	    case Kind::CONST_BOOLEAN:
896	    {
897	      bool value = n.getConst<bool>();
898	      std::string constraint = value ? "x[1] = x[1];" : "1 = 0;";
899	      std::vector<std::string> constraints{constraint};
900	      return {constraints, n};
901	    }
902	    case Kind::LT:
903	    case Kind::GT:
904	    case Kind::LEQ:
905	    case Kind::GEQ:
906	    case Kind::EQUAL:
907	    {
908	      // a comparison "lhs <op> rhs;" with each side printed as a linear term
909	      linear::Polynomial l = linear::Polynomial::parsePolynomial(n[0]);
910	      linear::Polynomial r = linear::Polynomial::parsePolynomial(n[1]);
911	      std::string lTerm = getString(variables, l);
912	      std::string rTerm = getString(variables, r);
913	      std::string kString = k == Kind::LT    ? " < "
914	                            : k == Kind::GT  ? " > "
915	                            : k == Kind::LEQ ? " <= "
916	                            : k == Kind::GEQ ? " >= "
917	                                             : " = ";
918	      std::string constraint = lTerm + kString + rTerm + ";";
919	      std::vector<std::string> constraints{constraint};

100	  // also return the non-negativity constraints on the vector, which are a
101	  // necessary condition for membership in the star set (the set lives in the
102	  // non-negative orthant).
103	  Assert(n.getKind() == Kind::STAR_CONTAINS);
104	  Node lambda = n[0];
105	  std::vector<Node> vars(lambda[0].begin(), lambda[0].end());
106	  std::vector<Node> vecElements(n.begin() + 1, n.end());
107	
108	  Node substitute = lambda[1].substitute(
109	      vars.begin(), vars.end(), vecElements.begin(), vecElements.end());
110	
111	  Trace("liastar-ext-debug") << "n: " << n << std::endl;
112	  Trace("liastar-ext-debug") << "predicate : " << lambda[1] << std::endl;
113	  Node nonnegativeConstraints = nm->mkConst<bool>(true);
114	  for (const auto& v : vecElements)
115	  {
116	    Node nonnegative = nm->mkNode(Kind::GEQ, v, nm->mkConstInt(Rational(0)));
117	    nonnegativeConstraints = nonnegativeConstraints.andNode(nonnegative);
118	  }
119	  Trace("liastar-ext-debug") << "substitute: " << substitute << std::endl;
120	  return std::make_pair(substitute, nonnegativeConstraints);
121	}
