138	Node LiaStarUtils::toDNF(Node n, Env* e)
139	{
140	  // Normalize (no ites/negations) and then distribute AND over OR to reach
141	  // disjunctive normal form. `recursiveFlatten` collapses nested AND/OR so each
142	  // disjunct is a flat conjunction (a single cone).
143	  Node nnf = removeItesAndNots(n, e);
144	  Node dnf = distribute(nnf, e);
145	  Trace("liastar-ext-debug") << "dnf: " << dnf << std::endl;
146	  dnf = recursiveFlatten(e->getNodeManager(), dnf);
147	  // emit a query validating the distribution on the liastar-ext-smt trace
148	  traceDistinctQuery("dnf", nnf, dnf);
149	  return dnf;
150	}
151	
152	Node LiaStarUtils::recursiveFlatten(NodeManager* nm, Node n)
153	{
154	  // Collapse nested associative operators, e.g. (or a (or b c)) -> (or a b c)
155	  // and likewise for the conjuncts one level down, so a DNF is exactly two
156	  // levels deep: a flat OR of flat ANDs.
157	  Trace("liastar-ext-dnf") << "recursiveFlatten::n: " << n << std::endl;
158	  if (n.getNumChildren() == 0)
159	  {
160	    return n;
161	  }
162	  Node flat = expr::algorithm::flatten(nm, n);
163	  std::vector<Node> children;
164	  for (const auto& child : flat)
165	  {
166	    children.push_back(expr::algorithm::flatten(nm, child));
167	  }
168	  return nm->mkNode(flat.getKind(), children);
169	}
