171	Node LiaStarUtils::distribute(Node n, Env* e)
172	{
173	  // Recursively rewrite `n` into DNF by distributing AND over OR. Atoms and
174	  // boolean constants are returned unchanged; an OR distributes into its
175	  // children; an AND computes the cartesian product of its children's
176	  // disjuncts. Conjuncts found to be unsatisfiable (via `areAssertionsUnsat`)
177	  // are dropped, which keeps the number of cones down by avoiding empty ones.
178	  Assert(n.getType().isBoolean())
179	      << "Expected " << n << " to be boolean" << std::endl;
