    // User level when the literal was added to the trail
    int d_user_level;
    // User level at which this literal was introduced
    int d_intro_level;
    // The index in the trail
    int d_trail_index;

    VarData(CRef reason,
            int level,
            int user_level,
            int intro_level,
            int trail_index)
